time_t standard_time;
struct tm broken_time = {0};

broken_time.tm_year = 124;  // 2024 (Years since 1900)
broken_time.tm_mon  = 5;    // June (0-11)
broken_time.tm_mday = 15;
broken_time.tm_hour = 10;
broken_time.tm_min  = 30;
broken_time.tm_isdst = -1;  // Determine DST automatically

standard_time = mktime(&broken_time);

// Result: seconds since Epoch (local time)
// mktime also normalizes broken_time fields (e.g., tm_wday)
// Returns (time_t)-1 on error.
